result.text:
export type Choice = { value: string; name: string };
export type Group = { group: string; name: string; options: Choice[] };
export type ConfigOption = {
  id: string;
  name: string;
  type: string;
  category?: string | null;
  currentValue: string;
  options: (Choice | Group)[];
};
export type Resolution = {
  status: "missing-selector" | "no-request" | "unknown-choice" | "ambiguous" | "unchanged" | "change";
  selectorId: string | null;
  value: string | null;
};

type Category = "model" | "mode" | "thought_level";

function tokens(option: ConfigOption): Set<string> {
  const parts = (option.id + " " + option.name).split(/[^A-Za-z0-9]+/);
  const out = new Set<string>();
  for (const part of parts) {
    if (part !== "") out.add(part.toLowerCase());
  }
  return out;
}

function matchesFallback(option: ConfigOption, category: Category): boolean {
  const t = tokens(option);
  switch (category) {
    case "model":
      return t.has("model");
    case "mode":
      return t.has("mode") || (t.has("permission") && t.has("policy"));
    case "thought_level":
      return (t.has("thought") && t.has("level")) || (t.has("reasoning") && t.has("effort"));
    default:
      return false;
  }
}

function findSelector(options: ConfigOption[], category: Category): ConfigOption | undefined {
  const eligible = options.filter(option => option.type === "select");
  const exact = eligible.find(option => option.category === category);
  if (exact) return exact;
  return eligible.find(
    option =>
      (option.category === undefined || option.category === null || option.category === "") &&
      matchesFallback(option, category)
  );
}

function isGroup(item: Choice | Group): item is Group {
  return "group" in item && Array.isArray((item as Group).options);
}

function flatten(items: (Choice | Group)[]): Choice[] {
  const out: Choice[] = [];
  for (const item of items) {
    if (isGroup(item)) {
      for (const choice of item.options) out.push(choice);
    } else {
      out.push(item);
    }
  }
  return out;
}

export function resolveSelector(options: ConfigOption[], category: Category, request: string): Resolution {
  const selector = findSelector(options, category);
  if (!selector) return { status: "missing-selector", selectorId: null, value: null };

  const selectorId = selector.id;
  const wanted = request.trim();
  if (wanted === "") return { status: "no-request", selectorId, value: null };

  const choices = flatten(selector.options);
  const wantedLower = wanted.toLowerCase();
  const tiers: ((choice: Choice) => boolean)[] = [
    choice => choice.value === wanted,
    choice => choice.name === wanted,
    choice => choice.value.toLowerCase() === wantedLower,
    choice => choice.name.toLowerCase() === wantedLower,
  ];

  for (const test of tiers) {
    const values = new Set<string>();
    for (const choice of choices) {
      if (test(choice)) values.add(choice.value);
    }
    if (values.size === 0) continue;
    if (values.size > 1) return { status: "ambiguous", selectorId, value: null };
    const value = values.values().next().value as string;
    return { status: value === selector.currentValue ? "unchanged" : "change", selectorId, value };
  }

  return { status: "unknown-choice", selectorId, value: null };
}
